import math
from collections.abc import Mapping
from numbers import Real


def _vector3(value, name, positive=False):
    if not isinstance(value, (list, tuple)) or len(value) != 3:
        raise ValueError(f'{name} must contain exactly three numbers')
    result = []
    for item in value:
        if isinstance(item, bool) or not isinstance(item, Real):
            raise ValueError(f'{name} must contain real numbers, not booleans')
        try:
            number = float(item)
        except (OverflowError, ValueError) as exc:
            raise ValueError(f'{name} contains an unsupported number') from exc
        if not math.isfinite(number):
            raise ValueError(f'{name} must contain finite numbers')
        if positive and number <= 0:
            raise ValueError(f'{name} entries must be strictly positive')
        result.append(number)
    return result


def run(arguments):
    """Project an axis-aligned box onto a plane normal to direction.

    dimensions_m: three positive side lengths along X, Y, Z, in metres.
    direction: three finite components of a nonzero viewing direction.
    Raises ValueError for invalid inputs or unrepresentable output.
    """
    if not isinstance(arguments, Mapping):
        raise ValueError('arguments must be a mapping')
    if 'dimensions_m' not in arguments or 'direction' not in arguments:
        raise ValueError('dimensions_m and direction are required')

    x, y, z = _vector3(arguments['dimensions_m'], 'dimensions_m', positive=True)
    direction = _vector3(arguments['direction'], 'direction')
    scale = max(abs(component) for component in direction)
    if scale == 0:
        raise ValueError('direction must be nonzero')

    # Scale first so normalization cannot overflow for large components.
    scaled = [abs(component) / scale for component in direction]
    norm = math.hypot(*scaled)
    nx, ny, nz = [component / norm for component in scaled]

    # A = yz*|nx| + xz*|ny| + xy*|nz| for a unit direction n.
    terms = []
    for a, b, weight in ((y, z, nx), (x, z, ny), (x, y, nz)):
        if weight != 0:
            terms.append((a * weight) * b)
    try:
        area = math.fsum(terms)
    except OverflowError as exc:
        raise ValueError('projected area exceeds floating-point range') from exc
    if not math.isfinite(area) or area <= 0:
        raise ValueError('projected area is outside the supported numerical range')

    return {'projected_area_m2': area, 'fidelity': 'bounding_box_proxy'}
